arguments.command:
set -e
python3 - <<'PY'
from pathlib import Path

nginx_conf = Path('/etc/nginx/nginx.conf')
text = nginx_conf.read_text()
zone = '\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;\n'
log_format = '\tlog_format benchmark \'$time_local "$request_method" $status "$http_user_agent"\';\n'
if 'zone=benchmark_limit:10m' not in text:
    text = text.replace('http {\n', 'http {\n\n' + zone, 1)
if 'log_format benchmark ' not in text:
    marker = zone if zone in text else 'http {\n'
    text = text.replace(marker, marker + log_format, 1)
nginx_conf.write_text(text)

site = Path('/etc/nginx/conf.d/benchmark-site.conf')
site.write_text('''server {
    listen 8080;
    listen [::]:8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;

    error_page 404 /404.html;

    location = /404.html {
        internal;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
''')
site.chmod(0o644)

root = Path('/var/www/html')
root.mkdir(parents=True, exist_ok=True)
(root / 'index.html').write_text('Welcome to the benchmark webserver\n')
(root / '404.html').write_text('Page not found - Please check your URL\n')
for page in (root / 'index.html', root / '404.html'):
    page.chmod(0o644)

default = Path('/etc/nginx/sites-enabled/default')
if default.is_symlink() or default.exists():
    default.unlink()
PY
printf '%s\n' 'Nginx benchmark files configured.'

